#include <vector>
#include <queue>
#include <unordered_set>
#include <numeric>

class Solution {
public:
    std::vector<int> remainingMethods(int n, int k, std::vector<std::vector<int>>& invocations) {
        std::vector<std::vector<int>> adj(n);
        for (const auto& edge : invocations) {
            adj[edge[0]].push_back(edge[1]);
        }

        std::vector<bool> suspicious(n, false);
        std::queue<int> q;
        q.push(k);
        suspicious[k] = true;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) {
                if (!suspicious[v]) {
                    suspicious[v] = true;
                    q.push(v);
                }
            }
        }

        for (const auto& edge : invocations) {
            if (!suspicious[edge[0]] && suspicious[edge[1]]) {
                std::vector<int> all(n);
                std::iota(all.begin(), all.end(), 0);
                return all;
            }
        }

        std::vector<int> res;
        for (int i = 0; i < n; ++i) {
            if (!suspicious[i]) res.push_back(i);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> remainingMethods(int n, int k, int[][] invocations) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] edge : invocations) {
            adj.get(edge[0]).add(edge[1]);
        }

        boolean[] suspicious = new boolean[n];
        Queue<Integer> q = new LinkedList<>();
        q.offer(k);
        suspicious[k] = true;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj.get(u)) {
                if (!suspicious[v]) {
                    suspicious[v] = true;
                    q.offer(v);
                }
            }
        }

        for (int[] edge : invocations) {
            if (!suspicious[edge[0]] && suspicious[edge[1]]) {
                List<Integer> all = new ArrayList<>();
                for (int i = 0; i < n; i++) all.add(i);
                return all;
            }
        }

        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (!suspicious[i]) res.add(i);
        }
        return res;
    }
}

var remainingMethods = function(n, k, invocations) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of invocations) {
        adj[u].push(v);
    }

    const suspicious = new Uint8Array(n);
    const q = [k];
    suspicious[k] = 1;

    let head = 0;
    while (head < q.length) {
        const u = q[head++];
        for (const v of adj[u]) {
            if (!suspicious[v]) {
                suspicious[v] = 1;
                q.push(v);
            }
        }
    }

    for (const [u, v] of invocations) {
        if (!suspicious[u] && suspicious[v]) {
            const all = [];
            for (let i = 0; i < n; i++) all.push(i);
            return all;
        }
    }

    const res = [];
    for (let i = 0; i < n; i++) {
        if (!suspicious[i]) res.push(i);
    }
    return res;
};
